-- ═══════════════════════════════════════════════════════════════════
-- Reglamento de la Ley Número 561 de Tránsito y Seguridad Vial para el
-- Estado de Veracruz de Ignacio de la Llave (municipio de Misantla)
--
-- Reemplaza el catálogo de San Pedro Garza García (articulos.sql), que queda
-- inactivo como historial. Fuentes:
--   * Tabulador de infracciones 2026 de la Dirección General de Tránsito y
--     Seguridad Vial (art. 333 del Reglamento): infracción, artículos,
--     clasificación (leve, grave, muy grave), UMA y UMA con agravante.
--   * Texto del Reglamento: compilación de la CNDH, publicado en la G.O.E.
--     el 16-jun-2015, última reforma incorporada el 1-may-2020.
--
-- Reglas del art. 330:
--   * Leve 5–15 UMA, grave 16–30, muy grave 31–40, conducir en estado de
--     ebriedad 80–115; amonestación verbal y arresto sin multa.
--   * Descuento del 75% si se paga dentro de 5 días y del 50% del 6.º al 10.º;
--     sin descuento cuando se conduzca en estado de ebriedad (columna grave).
--
-- Correr después de articulos.sql. Es idempotente.
-- ═══════════════════════════════════════════════════════════════════

alter table public.catalogo_infracciones add column if not exists clasificacion text not null default '';
alter table public.catalogo_infracciones add column if not exists categoria text not null default '';
alter table public.catalogo_infracciones add column if not exists nota text not null default '';
alter table public.catalogo_infracciones add column if not exists articulos_ref text[] not null default '{}';
alter table public.catalogo_infracciones alter column cuotas_min drop not null;
alter table public.catalogo_infracciones alter column cuotas_max drop not null;
comment on column public.catalogo_infracciones.grave is 'true = se paga íntegra, sin descuento';

alter table public.configuracion add column if not exists descuento2_pct integer default 50;
alter table public.configuracion add column if not exists dias_descuento2 integer default 10;

create table if not exists public.reglamento_articulos (
  numero text primary key,
  texto  text not null
);
alter table public.reglamento_articulos enable row level security;
drop policy if exists personal_select on public.reglamento_articulos;
create policy personal_select on public.reglamento_articulos for select to authenticated using (public.mi_rol() is not null);

-- El catálogo de San Pedro Garza García queda como historial
update public.catalogo_infracciones set activo = false, tipo_rapido = null where numero < 1000;

on conflict (numero) do nothing;

on conflict (numero) do nothing;

update public.configuracion set
  municipio = 'Misantla',
  estado = 'Veracruz de Ignacio de la Llave',
  reglamento = 'Reglamento de la Ley Número 561 de Tránsito y Seguridad Vial para el Estado de Veracruz de Ignacio de la Llave',
  fundamento_general = 'Artículos 16, 21 y 115, fracción III, inciso h), de la Constitución Política de los Estados Unidos Mexicanos; Ley Número 561 de Tránsito y Seguridad Vial para el Estado de Veracruz de Ignacio de la Llave; y artículos 330, 331, 332 y 333 de su Reglamento',
  descuento_pct = 75, dias_descuento = 5,
  descuento2_pct = 50, dias_descuento2 = 10
where id = 1;

-- ── Fundamento: "198, 220 F. V" → "Artículos 198, 220 fracción V, del Reglamento …" ──
create or replace function public.fundamento_de(p_numero integer)
returns text
language sql stable
set search_path = public
as $$
  select case when c.articulo ~ '^\d+$' or c.articulo !~ '\d+\D+\d' or c.fraccion <> '' then 'Artículo ' else 'Artículos ' end
    || case when c.fraccion = '' and c.inciso = '' then
         regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(c.articulo,
           '\m[Pp]\.?,?\s*(?=\d)', 'párrafo ', 'g'),
           '\m[Ff]\.\s*|\mF\s+(?=[IVXL])', 'fracción ', 'g'),
           '\m[Ii][Nn][Cc]\.\s*', 'inciso ', 'g'),
           '\mAp\.\s*', 'apartado ', 'g'),
           '\mY\M', 'y', 'g')
       else c.articulo
         || case when c.fraccion = '' then ''
                 when c.fraccion ilike '%párrafo%' or c.fraccion ilike 'anexo%' then ', ' || c.fraccion
                 when c.fraccion ~ '(,| y )' then ', fracciones ' || c.fraccion
                 else ', fracción ' || c.fraccion end
         || case when c.inciso = '' then ''
                 when c.inciso ~ '(,| y )' then ', incisos ' || c.inciso
                 else ', inciso ' || c.inciso || ')' end
       end
    || ', del ' || coalesce(cfg.reglamento, 'Reglamento de Tránsito')
  from public.catalogo_infracciones c
  left join public.configuracion cfg on cfg.id = 1
  where c.numero = p_numero
$$;

-- ── Monto: entre la UMA base y la UMA con agravante; amonestación/arresto sin multa ──
create or replace function public.aplicar_fundamento()
returns trigger
language plpgsql security definer
set search_path = public
as $$
declare
  c public.catalogo_infracciones%rowtype;
  v_uma numeric;
begin
  if new.catalogo_numero is null or current_setting('transito.migrando', true) = '1' then return new; end if;
  select * into c from public.catalogo_infracciones where numero = new.catalogo_numero;
  if tg_op = 'INSERT' or new.catalogo_numero is distinct from old.catalogo_numero then
    if not c.activo then raise exception 'La infracción % del catálogo ya no está vigente', c.numero; end if;
    new.fundamento := public.fundamento_de(c.numero);
  end if;
  if c.cuotas_min is null then
    new.monto := 0;   -- amonestación verbal o arresto: sin multa en UMA
    return new;
  end if;
  if tg_op = 'INSERT' or new.monto is distinct from old.monto or new.catalogo_numero is distinct from old.catalogo_numero then
    select valor_uma into v_uma from public.configuracion where id = 1;
    if v_uma is not null and (new.monto < floor(c.cuotas_min * v_uma) or new.monto > ceil(c.cuotas_max * v_uma)) then
      raise exception 'El monto debe estar entre $% (% UMA) y $% (% UMA con agravante) — %',
        to_char(floor(c.cuotas_min * v_uma), 'FM999,999'), c.cuotas_min,
        to_char(ceil(c.cuotas_max * v_uma), 'FM999,999'), c.cuotas_max, public.fundamento_de(c.numero);
    end if;
  end if;
  return new;
end $$;

-- ── Cobro con los dos tramos de descuento del art. 330 (75% / 50%) ──
create or replace function public.registrar_pago(
  p_infraccion_id bigint, p_aplicar_descuento boolean, p_metodo text, p_notas text default '')
returns public.pagos
language plpgsql security definer
set search_path = public
as $$
declare
  v_inf public.infracciones%rowtype;
  v_cfg public.configuracion%rowtype;
  v_cajero text;
  v_desc numeric := 0;
  v_pago public.pagos%rowtype;
begin
  select nombre into v_cajero from public.usuarios where auth_id = auth.uid() and activo;
  if v_cajero is null then raise exception 'Sesión no válida'; end if;
  if p_metodo not in ('efectivo','tarjeta','transferencia') then raise exception 'Método de pago inválido'; end if;

  select * into v_inf from public.infracciones where id = p_infraccion_id for update;
  if not found then raise exception 'Infracción no encontrada'; end if;
  if v_inf.estado in ('pagada','cancelada') or exists (select 1 from public.pagos where infraccion_id = p_infraccion_id) then
    raise exception 'La infracción % ya está %', v_inf.folio, case when v_inf.estado = 'cancelada' then 'cancelada' else 'pagada' end;
  end if;

  select * into v_cfg from public.configuracion where id = 1;
  if p_aplicar_descuento then
    if exists (select 1 from public.catalogo_infracciones where numero = v_inf.catalogo_numero and grave) then
      raise exception 'Esta infracción se paga íntegra, sin descuento (conducir en estado de ebriedad)';
    end if;
    if now() - v_inf.fecha <= make_interval(days => coalesce(v_cfg.dias_descuento, 5)) then
      v_desc := coalesce(v_cfg.descuento_pct, 0);
    elsif v_cfg.dias_descuento2 is not null and now() - v_inf.fecha <= make_interval(days => v_cfg.dias_descuento2) then
      v_desc := coalesce(v_cfg.descuento2_pct, 0);
    else
      raise exception 'El periodo de descuento ya terminó';
    end if;
  end if;

  values (v_inf.id, v_inf.folio, v_inf.monto, v_desc, round(v_inf.monto * (1 - v_desc / 100.0)), p_metodo, v_cajero, coalesce(p_notas, ''))
  returning * into v_pago;

  update public.infracciones set estado = 'pagada' where id = v_inf.id;
  return v_pago;
end $$;
revoke all on function public.registrar_pago(bigint, boolean, text, text) from public, anon;
grant execute on function public.registrar_pago(bigint, boolean, text, text) to authenticated;

-- ── Parámetros públicos con los dos tramos (portal ciudadano) ──
create or replace function public.parametros_descuento()
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select jsonb_build_object(
    'descuento_pct', coalesce(descuento_pct, 0), 'dias_descuento', coalesce(dias_descuento, 5),
    'descuento2_pct', coalesce(descuento2_pct, 0), 'dias_descuento2', dias_descuento2,
    'dias_limite', coalesce(dias_limite, 30))
  from public.configuracion where id = 1
$$;
grant execute on function public.parametros_descuento() to anon, authenticated;

-- ── Vincular las infracciones registradas al catálogo de Veracruz (por tipo),
-- sin fundamento ni validación de monto: se emitieron antes.
select set_config('transito.migrando', '1', false);
update public.infracciones i set catalogo_numero = c.numero
from public.catalogo_infracciones c
where c.activo and c.tipo_rapido = i.tipo and (i.catalogo_numero is null or i.catalogo_numero < 1000);
select set_config('transito.migrando', '', false);
